 @MockBean cn.iocoder.yudao.module.system.api.user.AdminUserApi users;
 @MockBean cn.iocoder.yudao.module.system.api.permission.PermissionApi permissions;
 long p; long r1,r2,s,rel1,rel2;
 String scope="{\"entities\":[101],\"organizations\":[201],\"workerTypes\":[\"TEST\"],\"scenarios\":[\"TEST\"],\"from\":\"2026-10-01\",\"to\":\"2026-10-31\",\"explanation\":\"TEST\"}";
 @BeforeEach void setup(){
  cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder.setTenantId(1L);
  when(permissions.hasAnyPermissions(anyLong(),anyString())).thenReturn(true);
  for(long id=1;id<=4;id++)when(users.getUser(id)).thenReturn(new cn.iocoder.yudao.module.system.api.user.dto.AdminUserRespDTO().setId(id).setStatus(0));
  HrmPayrollRequirementProjectDO project=new HrmPayrollRequirementProjectDO().setName("TEST S3").setProjectKey("TEST_S3").setOwnerId(1L).setProjectScopeVersion(1).setMetadataVersion(1).setScopeJson(scope).setCustomSequence(0L);projects.insert(project);p=project.getId();
  for(long id=1;id<=4;id++)grant(p,id,String.join(",",HrmPayrollRequirementAccessService.ACTIONS));
  r1=req("R1");r2=req("R2");s=source("TEST SOURCE");rel1=link(s,r1);rel2=link(s,r2);
 }
 @AfterEach void clear(){cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder.clear();}
 void grant(long project,long user,String actions){HrmPayrollRequirementProjectGrantDO g=new HrmPayrollRequirementProjectGrantDO();g.setProjectId(project);g.setUserId(user);g.setActions(actions);g.setFullProject(true);g.setCeilingJson(scope.replace("[101]","[101,102]").replace("2026-10-31","2026-12-31"));g.setValidFrom(LocalDate.of(2026,1,1));g.setValidTo(LocalDate.of(2027,12,31));g.setEvidence("TEST independent fixture root, not formal approval");grants.insert(g);}
 <T extends Context>T ctx(T c,Long id){c.setProjectId(p);c.setProjectScopeVersion(projects.selectById(p).getProjectScopeVersion());c.setId(id);c.setVersion(id==null?null:records.selectById(id).getVersion());c.setReason("TEST execution");return c;}
 long req(String title){HrmPayrollRequirementSaveReqVO q=new HrmPayrollRequirementSaveReqVO();q.setProjectId(p);q.setProjectScopeVersion(1);q.setScopeMode("INHERIT");q.setCode("CUSTOM-0000");q.setModule("COL");q.setDescription(title);q.setPriority(2);q.setBusinessContextJson("{\"role\":\"TEST HR\",\"scenario\":\"TEST monthly\",\"goal\":\"TEST collect\",\"expected\":\"TEST expected\",\"normalCase\":\"TEST normal\",\"exceptionCase\":\"TEST exception\",\"calculation\":\"TEST rule\",\"unit\":\"TEST hour\",\"precision\":\"2\",\"validity\":\"TEST 2026-10\",\"ruleException\":\"TEST review\"}");q.setStatus("PENDING");q.setReadiness("READY");q.setRuleVersion("TEST RULE V1");q.setSourceApplicability("APPLICABLE");q.setAcceptance("TEST expected result");q.setEvidence("TEST authorized synthetic confirmation");long id=reqService.save(q,1L);reqService.assign(id,requirements.selectById(id).getVersion(),2L,1L);return id;}
 Source spec(String title){Source x=new Source();x.setName(title);x.setModule("COL");x.setScopeJson(scope);x.setOwnerId(1L);x.setTechnicalContact("TEST IT");x.setAcquisition("TEST file");x.setSpecification("TEST contract v1");x.setUniqueKey("employee,period");x.setEmployeeMatch("employee test ID");x.setFrequency("monthly");x.setCutoff("month end");x.setVolume("2 virtual rows");x.setQualityRule("QS RULE V1");Field f=new Field();f.setName("hours");f.setMeaning("TEST working time");f.setType("decimal");f.setUnit("minute");f.setRequired(true);x.setFields(Arrays.asList(f));return x;}
 long source(String title){SourceSave c=ctx(new SourceSave(),null);c.setSource(spec(title));return service.saveSource(c,1L);}
 long link(long src,long req){RelationSave c=ctx(new RelationSave(),null);Relation r=new Relation();r.setSourceId(src);r.setRequirementId(req);r.setConsumptionRule("QC RULE V1");Mapping m=new Mapping();m.setSourceField("hours");m.setPageField("workingHours");m.setMeaning("TEST time");m.setType("decimal");m.setUnit("hour");m.setRequired(true);m.setTransform("divide by 60");m.setNullRule("reject");m.setDuplicateRule("reject");m.setPeriodRule("same month");m.setExceptionRule("manual review");r.setFields(Arrays.asList(m));c.setRelation(r);return service.saveRelation(c,1L);}
 Source sourceData(){return JsonUtils.parseObject(records.selectById(s).getDataJson(),Source.class);}
 void saveSource(Source x){SourceSave c=ctx(new SourceSave(),s);c.setSource(x);service.saveSource(c,1L);}
 @SuppressWarnings("unchecked") Map<String,Object> detail(long id,String kind){return (Map<String,Object>)service.detail(p,kind,id,1L);}
 void verify(long id,String layer,String result){Verify c=ctx(new Verify(),id);c.setLayer(layer);c.setResult(result);c.setReference("TEST independently executed check");c.setSampleDigest("TEST D1 immutable input");c.setExpectedBinding((String)((Map<?,?>)detail(id,layer.equals("QS")||layer.equals("SOURCE_SEMANTIC")?"SOURCE":"RELATION").get("bindings")).get(layer));try{service.verify(c,1L);}catch(RuntimeException e){throw new AssertionError("Verification failed: "+layer+" object "+id,e);}}
 void supply(String state,boolean replace){Supply c=ctx(new Supply(),s);c.setSupply(state);c.setReplaceDelivery(replace);c.setDeliveryDigest("TEST D1 immutable input");c.setDeliveryReference("TEST redacted sample D1");service.supply(c,1L);}
 void baseline(){supply("PROVIDED",true);verify(s,"SOURCE_SEMANTIC","PASS");verify(rel1,"RELATION_SEMANTIC","PASS");verify(rel2,"RELATION_SEMANTIC","PASS");verify(s,"QS","PASS");verify(rel1,"QC","PASS");verify(rel2,"QC","PASS");confirm(r1);confirm(r2);assertEquals(2,available());}
 void confirm(long req){reqService.confirm(req,requirements.selectById(req).getVersion(),2L);}
 int available(){return (Boolean.TRUE.equals(detail(rel1,"RELATION").get("available"))?1:0)+(Boolean.TRUE.equals(detail(rel2,"RELATION").get("available"))?1:0);}
 @Test void manyToManyAndCopyHaveIndependentIdentitiesAndNoInheritedReadiness(){baseline();long second=source("TEST second");long thirdRel=link(second,r1);assertNotEquals(rel1,thirdRel);HrmPayrollRequirementProjectDO target=new HrmPayrollRequirementProjectDO().setProjectKey("TEST_TARGET").setName("TEST target").setScopeJson(scope).setProjectScopeVersion(1).setOwnerId(1L);projects.insert(target);grant(target.getId(),1,String.join(",",HrmPayrollRequirementAccessService.ACTIONS));Copy c=new Copy();c.setProjectId(target.getId());c.setProjectScopeVersion(1);c.setSourceProjectId(p);c.setSourceId(s);c.setSourceVersion(records.selectById(s).getVersion());c.setReason("TEST explicit copy");long copy=service.copy(c,1L);Source x=JsonUtils.parseObject(records.selectById(copy).getDataJson(),Source.class);assertEquals("UNINVENTORIED",x.getSupply());assertEquals(0,x.getDeliveryVersion());assertEquals(s,x.getCopiedFromSourceId());Source original=sourceData();original.getFields().get(0).setUnit("hour");saveSource(original);assertEquals("minute",JsonUtils.parseObject(records.selectById(copy).getDataJson(),Source.class).getFields().get(0).getUnit());}
 @Test void confirmationCanPrecedeSupplyAndCannotBeCreatedBySave(){confirm(r1);HrmPayrollRequirementDO r=requirements.selectById(r1);assertEquals("CONFIRMED",r.getStatus());assertNotNull(r.getConfirmedTupleJson());assertEquals("MISSING",service.readiness(r));assertNull(r.getSourceOwnerId());assertTrue(r.getConfirmedTupleJson().contains("mappingVersion"));HrmPayrollRequirementSaveReqVO q=JsonUtils.parseObject(JsonUtils.toJsonString(requirements.selectById(r2)),HrmPayrollRequirementSaveReqVO.class);q.setStatus("CONFIRMED");assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->reqService.save(q,1L));}
