 @Test void oldBindingAndOldObjectVersionCannotBeUsedToVerify(){baseline();Map<?,?> binding=(Map<?,?>)detail(rel1,"RELATION").get("bindings");String old=(String)binding.get("QC");RelationSave change=ctx(new RelationSave(),rel1);Relation r=JsonUtils.parseObject(records.selectById(rel1).getDataJson(),Relation.class);r.setConsumptionRule("QC RULE V2");change.setRelation(r);service.saveRelation(change,1L);Verify c=ctx(new Verify(),rel1);c.setLayer("QC");c.setResult("PASS");c.setReference("TEST");c.setSampleDigest("D1");c.setExpectedBinding(old);assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->service.verify(c,1L));assertEquals(1,available());}
