 void action(long id,String a,long actor){IssueAction c=ctx(new IssueAction(),id);c.setAction(a);c.setEvidence("TEST independently reviewed evidence");c.setExpectedBinding((String)detail(id,"ISSUE").get("binding"));c.setDueDate("2026-11-30");service.issueAction(c,actor);}
