 @Test void fixedShanghaiClockCoversAllOverdueStatesAndClosedHistory(){Clock clock=Clock.fixed(Instant.parse("2026-10-17T01:00:00Z"),ZoneOffset.UTC);for(String state:Arrays.asList("OPEN","PROCESSING","REVIEW")){Issue i=new Issue();i.setState(state);i.setDueDate("2026-10-16");assertEquals(true,HrmPayrollWorkbenchService.dates(i,clock).get("overdue"));i.setDueDate("2026-10-17");assertEquals(false,HrmPayrollWorkbenchService.dates(i,clock).get("overdue"));}Issue closed=new Issue();closed.setState("CLOSED");closed.setDueDate("2026-10-16");closed.setWasOverdue(true);assertEquals(false,HrmPayrollWorkbenchService.dates(closed,clock).get("unresolved"));assertEquals(false,HrmPayrollWorkbenchService.dates(closed,clock).get("overdue"));assertEquals(true,HrmPayrollWorkbenchService.dates(closed,clock).get("wasOverdue"));}
